// Compile all research items into a structured prompt input
const items = $input.all().map(i => i.json);

if (items.length === 0) {
  return { json: { skip: true, message: 'No new research items this week.' } };
}

// Group by category for structured analysis
const grouped = {};
for (const item of items) {
  const cat = item.properties?.Category?.select?.name || 'uncategorized';
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push({
    title: item.properties?.title?.title?.[0]?.text?.content || item.properties?.Name?.title?.[0]?.text?.content || 'Untitled',
    score: item.properties?.['Relevance Score']?.number || 0,
    angle: item.properties?.['Newsletter Angle']?.rich_text?.[0]?.text?.content || '',
    summary: item.properties?.Summary?.rich_text?.[0]?.text?.content || '',
    source: item.properties?.Source?.select?.name || '',
    tier: item.properties?.['Newsletter Tier']?.select?.name || 'all',
    url: item.properties?.URL?.url || '',
    notionId: item.id
  });
}

// Build the research compilation
let compilation = `RESEARCH ITEMS THIS WEEK (${items.length} total):\n\n`;
for (const [cat, catItems] of Object.entries(grouped)) {
  compilation += `## ${cat.toUpperCase()} (${catItems.length} items)\n`;
  for (const item of catItems.sort((a, b) => b.score - a.score)) {
    compilation += `- [Score ${item.score}] ${item.title}\n`;
    compilation += `  Source: ${item.source} | Tier: ${item.tier}\n`;
    compilation += `  Angle: ${item.angle}\n`;
    compilation += `  Summary: ${item.summary.substring(0, 200)}\n\n`;
  }
}

return {
  json: {
    skip: false,
    compilation,
    item_count: items.length,
    categories: Object.keys(grouped),
    notion_ids: items.map(i => i.id)
  }
};

// Extract brief text from Claude response
const response = $input.item.json;
const briefText = response.content?.[0]?.text || 'Error: No response from Claude';
const metadata = $('Compile Research').first().json;

const weekOf = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

return {
  json: {
    brief: briefText,
    week_of: weekOf,
    item_count: metadata.item_count,
    categories: metadata.categories,
    notion_ids: metadata.notion_ids,
    title: `Research Brief — Week of ${weekOf}`
  }
};

// Mark source research items as 'used' in Notion
// Returns list of Notion page IDs to update
const ids = $('Compile Research').first().json.notion_ids || [];
return ids.map(id => ({ json: { pageId: id } }));

